SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();
load "work/deg10/C236_resolution_20261030/geometry/quotient9_cusp_units_model.m";
load "work/deg10/C236_resolution_20261030/geometry/quotient9_cusp_permutations.m";
load "work/deg10/C236_resolution_20261030/geometry/deps/native_group_generators.m";
load "work/deg10/C236_resolution_20261030/geometry/deps/class_group_direct_RR_checked_v4_fastfb.m";
F:=RationalExtensionRepresentation(Z);coords:=[F!v:v in zcoords];assert Genus(F) eq 9;
base:=DivisorGroup(F)!Divisor(cs[CuspGlobalRational[1]]);assert Degree(base) eq 1;
cdivs:=[DivisorGroup(F)!Divisor(c):c in cs];assert Sort([Degree(D):D in cdivs]) eq Sort([1:i in [1..8]] cat [2:i in [1..12]]);
ivs:=ClassGroupAbelianInvariants(F:ReductionDivisor:=base,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G:=F`cld`Cl;ff:=F`cld`ZnToCl;Zn:=Domain(ff);fb:=Reverse([x`place:x in F`cld`fb]);fc:=[ff(Zn.i):i in [1..#fb]];
assert [v:v in Invariants(G)|v ne 0] eq [3,3,3,24,24,192];
GG,_,phi,witness:=MDClassGroupDirectRRCheckedV4FastFB(F,"work/deg10/C236_resolution_20261030/geometry/quotient9_cusp_RR.log");assert GG cmpeq G;
cc:=[phi(D-Degree(D)*base):D in cdivs];H:=sub<G|cc>;QH,qh:=quo<G|H>;assert Invariants(H) eq [3,3,3,24,24,24];assert #TorsionSubgroup(QH) eq 8;
A0:=F`cld`A1;pp,ee:=Support(A0);assert #pp eq 1 and ee[1] eq 1;ai:=Index(fb,pp[1]);assert ai gt 0;
function ER(v) return [[Integers()!x:x in Coefficients(Numerator(v))],[Integers()!x:x in Coefficients(Denominator(v))]];end function;
function EF(v) return [ER(x):x in Eltseq(F!v)];end function;
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function EP(pl) I:=Ideal(pl);return [*Order(I) eq OF select 1 else 0,Degree(pl),[EF(v):v in Basis(I)]*];end function;
flags:=[Order(Ideal(p)) eq OF select 1 else 0:p in fb];degs:=[Degree(p):p in fb];ideals:=[*[EF(v):v in Basis(Ideal(p))]:p in fb*];
bp,be:=Support(base);assert #bp eq 1 and be[1] eq 1;
out:=[*[ER(v):v in Coefficients(DefiningPolynomial(F))],flags,degs,ideals,[Eltseq(v):v in fc],[Eltseq(v):v in Rows(RelationMatrix(G))],[EF(v):v in coords],ai,[Degree(D):D in cdivs],[Eltseq(v):v in cc],[EP(Support(D)[1]):D in cdivs],EP(bp[1]),[Eltseq(v):v in Generators(H)]*];
Write("work/deg10/C236_resolution_20261030/geometry/quotient9_proven_picard.m",Sprint(out):Overwrite:=true);fprintf witness,"]\n";Flush(witness);
printf "C236_D10_QUOTIENT9_PROVEN_COMPLETE G=%o H=%o index=%o factorbase=%o cpu=%o\n",Invariants(G),Invariants(H),#TorsionSubgroup(QH),#fb,Cputime(tt);quit;
